def run_tool(name, payload, allowed_tools, max_chars):
    if name not in set(allowed_tools):
        raise PermissionError("Tool nicht erlaubt")
    if int(max_chars) <= 0:
        raise ValueError("max_chars muss positiv sein")
    payload = str(payload)
    if len(payload) > int(max_chars):
        raise ValueError("payload zu lang")
    return {"tool": name, "payload": payload}
